//! Cargo-driven `qcap.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fe9a000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fe9a000000u64)),
        o => panic!("qcap-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/directx/wine/qcap/qcap_classes_r.o", "engine:wine", "engine:c:wine_dll_canunload", "engine:c:strmbase", "engine:c:strmiids", "engine:uuid", "engine:oldnames", "import:msvfw32", "import:ole32", "import:oleaut32", "import:winmm", "import:user32", "import:gdi32", "import:advapi32", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body"],
        "x86_64" => &["dll/directx/wine/qcap/qcap_classes_r.o", "engine:wine", "engine:c:wine_dll_canunload", "engine:c:strmbase", "engine:c:strmiids", "engine:uuid", "engine:oldnames", "import:msvfw32", "import:ole32", "import:oleaut32", "import:winmm", "import:user32", "import:gdi32", "import:advapi32", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body"],
        "aarch64" => &["dll/directx/wine/qcap/qcap_classes_r.o", "engine:wine", "engine:c:wine_dll_canunload", "engine:c:strmbase", "engine:c:strmiids", "engine:uuid", "engine:oldnames", "import:msvfw32", "import:ole32", "import:oleaut32", "import:winmm", "import:user32", "import:gdi32", "import:advapi32", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/directx/wine/qcap",
        "dll/directx/wine/qcap",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "USE_NEW_WINE_REGISTER_RESOURCES",
        "WINVER=0x600",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x600",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("qcap_shims", &["dll/directx/wine/qcap/audiorecord.c", "dll/directx/wine/qcap/avico.c", "dll/directx/wine/qcap/avimux.c", "dll/directx/wine/qcap/capturegraph.c", "dll/directx/wine/qcap/filewriter.c", "dll/directx/wine/qcap/qcap_main.c", "dll/directx/wine/qcap/smartteefilter.c", "dll/directx/wine/qcap/v4l.c", "dll/directx/wine/qcap/vfwcapture.c"])
        .rc("dll/directx/wine/qcap/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/directx/wine/qcap/qcap.spec", "qcap.dll")
        .delay_import_lib("dll/win32/msvfw32/msvfw32.spec", "msvfw32.dll", "msvfw32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/winmm/winmm.spec", "winmm.dll", "winmm")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
